#!/bin/bash
# GENERATED by build.py recipe - do not edit by hand.
set -euxo pipefail
SRC=/src; OUT=/out
mkdir -p "$SRC" "$OUT"

echo "################ build deps ################"
dnf -y install --setopt=install_weak_deps=False git gcc gcc-c++ clang cmake ninja-build pkgconf-pkg-config meson autoconf automake libtool patch golang qt6-qtbase-devel qt6-qtbase-private-devel qt6-qtdeclarative-devel qt6-qtshadertools-devel qt6-qtimageformats qt6-qtsvg wayland-devel wayland-protocols-devel libxcb-devel vulkan-headers spirv-tools cli11-devel libqalculate-devel pipewire-devel aubio-devel lm_sensors-devel fftw-devel jemalloc-devel libdrm-devel mesa-libgbm-devel polkit-devel libunwind-devel libdwarf-devel binutils-devel pam-devel xkeyboard-config iniparser-devel fontconfig lua python3-devel python3-pip ffmpeg-free-devel libX11-devel libXcomposite-devel libXrandr-devel libXfixes-devel libXdamage-devel pulseaudio-libs-devel libva-devel libcap-devel extra-cmake-modules kf6-kconfig-devel kf6-kcolorscheme-devel kf6-kiconthemes-devel kf6-kconfigwidgets-devel kf6-ki18n-devel kf6-kcoreaddons-devel kf6-kguiaddons-devel kf6-kwindowsystem-devel kf6-kirigami-devel kf6-kcmutils-devel kf6-frameworkintegration-devel kdecoration-devel ca-certificates

# --- pinned fetch ------------------------------------------------------------
# Every source is pinned to an exact revision from deps.lock.json. A tarball
# whose digest does not match aborts the build.
git_pin() {  # url sha dir [sparse-path ...]
  local url="$1" sha="$2" dir="$3"; shift 3
  if [ "$#" -gt 0 ]; then
    # Blobless + sparse: material-design-icons is ~24 GB and we need one TTF.
    git clone --quiet --filter=blob:none --no-checkout "$url" "$SRC/$dir"
    git -C "$SRC/$dir" sparse-checkout init --cone
    git -C "$SRC/$dir" sparse-checkout set "$@"
    git -C "$SRC/$dir" fetch --quiet --depth 1 origin "$sha"
  else
    git clone --quiet --filter=blob:none "$url" "$SRC/$dir"
  fi
  git -C "$SRC/$dir" checkout --quiet "$sha"
  got=$(git -C "$SRC/$dir" rev-parse HEAD)
  [ "$got" = "$sha" ] || { echo "!!! $dir pinned to $sha but got $got"; exit 1; }
}
tar_pin() {  # url sha256 dir
  curl -sSfL -o "$SRC/$3.tar.gz" "$1"
  echo "$2  $SRC/$3.tar.gz" | sha256sum -c - \
    || { echo "!!! $3 sha256 MISMATCH"; exit 1; }
  mkdir -p "$SRC/$3/extracted"
  # No -z: GNU tar sniffs the magic bytes on extract. The nerd-font releases are
  # .tar.xz while dart-sass and gpu-screen-recorder are .tar.gz, and forcing -z
  # made every xz archive fail with "not in gzip format".
  tar -xf "$SRC/$3.tar.gz" -C "$SRC/$3/extracted"
}

git_pin "https://github.com/caelestia-dots/cli" "ff8cae38bd4bea8d1827a0a6971d6763d58c570e" caelestia-cli
git_pin "https://github.com/caelestia-dots/caelestia" "f4bb062cc3c617f0fa16525a365097c9e4684d83" caelestia-dots
git_pin "https://github.com/caelestia-dots/shell" "a3a8fe59aba2c0048ab02dc817748678f96076ff" caelestia-shell
git_pin "https://github.com/Bali10050/darkly" "6fc65177b22983d54aa965ea3617f8c9d658f442" darkly
git_pin "https://github.com/jesseduffield/lazygit" "4c2ce238a925c41b6caee6dcf722984ff081774b" lazygit
git_pin "https://github.com/LukashonakV/cava" "f03278ef9e5e7948fb206453d2f02758f8db216c" libcava
git_pin "https://github.com/soramanew/m3shapes" "8a6fe8961749887d677700b6508e0c9249968b7e" m3shapes
git_pin "https://github.com/google/material-design-icons" "49d4db35df873165d6bd6ba09b063c7dafbac2f4" material-symbols variablefont
git_pin "https://github.com/kossLAN/qtengine" "1a8b9c5fd7ab695c71b1ac236953491088e152fb" qtengine
git_pin "https://git.outfoxxed.me/quickshell/quickshell" "4f508be500dea6e5732cc3d50382a0048b17e7b1" quickshell
git_pin "https://github.com/googlefonts/rubik" "e337a5f69a9bea30e58d05bd40184d79cc099628" rubik
tar_pin "https://github.com/ryanoasis/nerd-fonts/releases/download/v3.5.1/CascadiaCode.tar.xz" "ae598e9401e2846aa3ee364513715de0490b844a4b54f0768991f45f23aa8369" cascadia-code-nerd
tar_pin "https://github.com/sass/dart-sass/releases/download/1.105.1/dart-sass-1.105.1-linux-x64.tar.gz" "9046fdd4a31a524a0020298c55d9e155d4c22363ef268e8992574335a72c6a6f" dart-sass
tar_pin "https://dec05eba.com/snapshot/gpu-screen-recorder.git.5.12.3.tar.gz" "66b483f910a71d0b3320ca9a87cf8b16f97ca0db1dab324184c7c5a876203bdd" gpu-screen-recorder
tar_pin "https://github.com/ryanoasis/nerd-fonts/releases/download/v3.5.1/JetBrainsMono.tar.xz" "04d5e8f903693f9dd13e16f867e994834e681eb3c72c0d337a770dcda09010cf" jetbrains-mono-nerd

# --- 1. fonts ---------------------------------------------------------------
# caelestia-shell resolves its icon family as "Material Symbols Rounded" and
# its mono family as "CaskaydiaCove NF". Without them every icon renders as
# its literal ligature text (clear_day, arrow_forward, ...) instead of glyphs.
echo "################ fonts ################"
install -d /usr/share/fonts/material-symbols /usr/share/fonts/nerd
install -m 0644 "$SRC/material-symbols/variablefont/MaterialSymbolsRounded"[FILL,GRAD,opsz,wght].ttf \
  /usr/share/fonts/material-symbols/
install -m 0644 "$SRC"/cascadia-code-nerd/extracted/*.ttf /usr/share/fonts/nerd/
install -m 0644 "$SRC"/jetbrains-mono-nerd/extracted/*.ttf /usr/share/fonts/nerd/
fc-cache -f
fc-match "Material Symbols Rounded" | grep -q "Material Symbols Rounded" \
  || { echo "!!! Material Symbols Rounded did not register"; exit 1; }
fc-match "CaskaydiaCove NF" | grep -qi "caskaydia" \
  || { echo "!!! CaskaydiaCove NF did not register"; exit 1; }

# --- 2. libcava (meson) ------------------------------------------------------
cd "$SRC/libcava"
meson setup -Dbuild_target=lib -Dcava_font=false --prefix=/usr build
meson compile -C build
DESTDIR= meson install -C build
pkg-config --exists libcava || { echo "!!! libcava.pc missing"; exit 1; }

# --- 2. m3shapes (cmake) -----------------------------------------------------
cd "$SRC/m3shapes"
cmake -B build -G Ninja -DCMAKE_BUILD_TYPE=RelWithDebInfo -DCMAKE_INSTALL_PREFIX=/usr \
      -DINSTALL_QML_PREFIX=lib64/qt6/qml -DDISTRIBUTOR="caelestia-fedora"
cmake --build build
DESTDIR= cmake --install build

# --- 3. quickshell (cmake, vendored cpptrace) --------------------------------
# cpptrace is absent from Fedora, so VENDOR_CPPTRACE builds it from git.
cd "$SRC/quickshell"
cmake -GNinja -B build -DCMAKE_BUILD_TYPE=RelWithDebInfo -DCMAKE_INSTALL_PREFIX=/usr \
      -DDISTRIBUTOR="caelestia-fedora" -DVENDOR_CPPTRACE=ON \
      -DINSTALL_QML_PREFIX=lib64/qt6/qml
cmake --build build -j "$(nproc)"
DESTDIR= cmake --install build

# --- 4. caelestia-shell (cmake: extras + plugin + shell) ---------------------
cd "$SRC/caelestia-shell"
git rev-parse HEAD > REVISION
cmake -B build -G Ninja -DCMAKE_BUILD_TYPE=RelWithDebInfo -DCMAKE_INSTALL_PREFIX=/usr \
      -DENABLE_MODULES="extras;plugin;shell" \
      -DVERSION="$(git describe --tags --abbrev=0 2>/dev/null | sed 's/^v//' || echo 2.5.0)" \
      -DGIT_REVISION="$(git rev-parse HEAD)" -DDISTRIBUTOR="caelestia-fedora" \
      -DINSTALL_QSCONFDIR=/etc/xdg/quickshell/caelestia \
      -DINSTALL_QMLDIR=lib64/qt6/qml -DINSTALL_LIBDIR=lib64/caelestia
cmake --build build -j "$(nproc)"
DESTDIR= cmake --install build

# --- 5. caelestia-cli (wheel only) ------------------------------------------
# Only the wheel is shipped. Installing site-packages by hand is fragile: pip
# splits the package and its deps across lib/ and lib64/ on Fedora and the
# dist-info directories carry version numbers. The recipe pip-installs it in
# the final image instead.
cd "$SRC/caelestia-cli"
pip install --no-cache-dir build hatchling hatch-vcs
SETUPTOOLS_SCM_PRETEND_VERSION=1 python3 -m build --wheel --no-isolation
mkdir -p "$OUT/wheel"
cp dist/*.whl "$OUT/wheel/"

# --- 6. lazygit (go) ---------------------------------------------------------
cd "$SRC/lazygit"
go build -ldflags "-s -w -X main.version=$(git describe --tags --abbrev=0 2>/dev/null || echo dev)" \
      -o /usr/bin/lazygit .

# --- 7. gpu-screen-recorder (meson) ------------------------------------------
cd "$SRC/gpu-screen-recorder/extracted"
meson setup --prefix=/usr build
meson compile -C build
DESTDIR= meson install -C build

# --- 7b. qtengine + darkly (cmake, not packaged for Fedora) -----------------
# The image strips wayblue's QT_STYLE_OVERRIDE=adwaita-dark so that caelestia's
# qtengine theming is what actually themes Qt apps. Neither qtengine nor darkly
# exists in any enabled Fedora 44 repo, so both are built from source.
echo "################ qtengine ################"
cd "$SRC/qtengine"
# BUILD_QT5 defaults to ON in both qtengine and darkly, but Fedora 44 ships no
# Qt5 at all (it is EOL), so the Qt5 subdirectory fails find_package(Qt5 5.15)
# and takes the whole configure down with it.
cmake -B build -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=/usr \
      -DBUILD_QT5=OFF -DBUILD_QT6=ON
cmake --build build -j "$(nproc)"
DESTDIR= cmake --install build

echo "################ darkly ################"
cd "$SRC/darkly"
cmake -B build -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=/usr \
      -DBUILD_QT5=OFF -DBUILD_QT6=ON
cmake --build build -j "$(nproc)"
DESTDIR= cmake --install build

# --- 8. rubik font (not packaged on Fedora) ----------------------------------
# caelestia-shell uses Rubik for the clock and workspaces.
install -d /usr/share/fonts/rubik
install -m 0644 "$SRC"/rubik/fonts/variable/Rubik*.ttf /usr/share/fonts/rubik/
install -m 0644 "$SRC/rubik/OFL.txt" /usr/share/licenses/rubik/OFL.txt || true
fc-cache -f /usr/share/fonts/rubik

# --- 9. dart-sass (official release binary) ----------------------------------
# No Dart SDK is packaged for Fedora 44; GitHub publishes a first-party sha256
# digest for the asset, which tar_pin already verified.
rm -rf /opt/dart-sass
cp -a "$SRC/dart-sass/extracted/dart-sass" /opt/dart-sass
chmod +x /opt/dart-sass/sass /opt/dart-sass/src/dart
/opt/dart-sass/sass --version

# --- 9. caelestia dots ------------------------------------------------------
# The image must carry the dots itself: the builder stage is the only place
# they exist in CI, and firstboot has to deploy them from the image. Without
# this, ~/.config/hypr is never created and starthyprland falls back to a
# /usr/share/hyprland/hyprland.lua that does not exist, which locks the user
# out of SDDM entirely.
echo "################ dots ################"
install -d /usr/share/caelestia/dots
cp -a "$SRC/caelestia-dots/hypr" /usr/share/caelestia/dots/
[ -f /usr/share/caelestia/dots/hypr/hyprland.lua ] \
  || { echo "!!! dots missing hyprland.lua"; exit 1; }

# --- stage runtime artefacts -------------------------------------------------
# Only what the final image actually runs. Build headers, static archives,
# cmake/pkgconfig exports and the toolchain itself stay behind.
stage_path() {
  [ -e "$1" ] || { echo "!!! expected artefact missing: $1"; exit 1; }
  mkdir -p "$OUT$(dirname "$1")"
  cp -a "$1" "$OUT$1"
}
for a in \
    /usr/bin/quickshell \
    /usr/bin/lazygit \
    /usr/bin/gpu-screen-recorder \
    /usr/bin/gsr-kms-server \
    /usr/lib64/libm3shapes.so \
    /usr/lib64/libcava.so.1.0.0 \
    /usr/lib64/libcava.so.1 \
    /usr/lib64/libcava.so \
    /usr/lib64/caelestia \
    /usr/lib64/qt6/qml/Quickshell \
    /usr/lib64/qt6/qml/Caelestia \
    /usr/lib64/qt6/qml/M3Shapes \
    /usr/lib64/qt6/qml/QmlTime \
    /usr/share/applications/org.quickshell.desktop \
    /usr/share/icons/hicolor/scalable/apps/org.quickshell.svg \
    /usr/share/gpu-screen-recorder \
    /usr/share/fonts/rubik \
    /etc/xdg/quickshell/caelestia \
    /opt/dart-sass \
    /usr/share/fonts/material-symbols \
    /usr/share/fonts/nerd \
    /usr/share/caelestia/dots ; do
  stage_path "$a"
done

# qtengine and darkly install into these trees; stage whichever ones exist.
for a in /usr/lib64/qt6/plugins/platformthemes /usr/share/themes ; do
  [ -e "$a" ] && stage_path "$a"
done

echo "STAGED:"
find "$OUT" -maxdepth 3 -mindepth 1 | sort
echo "ALL BUILDS OK"
